#!/usr/bin/env python3
"""data/sfo_env_presets.js: the 14 real-weather presets of docs/research/environment_spec.md §10 for the browser
(?wx=<id> QA hook, js/env/presets.js) and SNAPSHOT_TAF (the TAF in force at the snapshot time). Generated from tools/env/fixtures/env_presets.json (tools/env/env_spec_checks.py)
- only the inputs (time, raw report, its source, the runway-configuration INPUT); the expected outputs stay in the
fixture for the tests. Reports: IEM ASOS archive (public domain) and the aviationweather.gov Data API (US Government
work). Showing them as a user-facing weather menu in the artifact is owner question Q8 (default: QA hook only).
Run: python3 tools/env/build_env_presets_js.py
"""
import json, os
HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(os.path.join(HERE, '..', '..'))
src = json.load(open(os.path.join(HERE, 'fixtures', 'env_presets.json')))
out = [{k: p[k] for k in ('id', 'time_utc', 'metar', 'source', 'runway_config_input')} for p in src['presets']]
# SNAPSHOT_TAF (spec 3.4): the KSFO TAF in force at the snapshot time (data/snapshot.js now = 2026-09-23T17:51:25Z) =
# the latest one issued at or before it, from the IEM AFOS archive of the NWS product TAFSFO (KMTR FTUS46),
# refs/cache/weather/iem_afos_TAFSFO_20260923.txt (SOURCES.json beside it; AWC keeps 30 days only)
import re
SNAP_ISSUE_MAX = '231751'           # DDhhmm of the snapshot time
taf_src = os.path.join(ROOT, 'refs', 'cache', 'weather', 'iem_afos_TAFSFO_20260923.txt')
snapshot_taf = None
ok = []
if os.path.exists(taf_src):
    text = open(taf_src, errors='replace').read()
    tafs = [(m.group(2), ' '.join(m.group(1).split())) for m in re.finditer(r'(TAF(?: AMD| COR)?\s+KSFO\s+(\d{6})Z.*?)=', text, re.S)]
    ok = [t for t in tafs if t[0] <= SNAP_ISSUE_MAX and t[0].startswith('23')]
    if ok:
        iss, raw = max(ok)
        snapshot_taf = {'raw': raw, 'issued': '2026-09-23T%s:%s:00Z' % (iss[2:4], iss[4:6]), 'source': 'NWS TAFSFO (KMTR) via the IEM AFOS archive, refs/cache/weather/iem_afos_TAFSFO_20260923.txt', 'n_archived_that_day': len(tafs)}
if os.path.exists(taf_src) and ok:
    # every TAF issued that day at or before the snapshot time (the app picks the latest issued <= min(t_env, snapshot):
    # light mode Dawn 13:45Z -> 231124Z; review truth2-7)
    snapshot_tafs = [{'raw': raw, 'issued': '2026-09-23T%s:%s:00Z' % (iss[2:4], iss[4:6])} for iss, raw in sorted(ok)]
else:
    snapshot_tafs = []
# SNAPSHOT_METARS (review truth2-7): the KSFO reports of the 24 h before the snapshot, observed at or before it, from the
# IEM ASOS archive (refs/cache/weather/iem_ksfo_20260922T18_20260923T18_metar.csv, public domain, SOURCES.json); type
# prefix: METAR at hh:56 (KSFO's routine minute, as js/env/wx/metar.js renderParams), SPECI otherwise (I)
import csv
SNAP_T = '2026-09-23 17:51'
met_src = os.path.join(ROOT, 'refs', 'cache', 'weather', 'iem_ksfo_20260922T18_20260923T18_metar.csv')
snapshot_metars = []
if os.path.exists(met_src):
    for r in csv.DictReader(open(met_src)):
        if r['valid'] <= SNAP_T and r['metar'].startswith('KSFO '):
            mm = r['valid'][-2:]
            snapshot_metars.append(('METAR ' if mm == '56' else 'SPECI ') + r['metar'].strip())
    snapshot_metars.sort(key=lambda x: x.split()[2], reverse=True)
path = os.path.join(ROOT, 'data', 'sfo_env_presets.js')
with open(path, 'w') as f:
    f.write('// generated by tools/env/build_env_presets_js.py from tools/env/fixtures/env_presets.json - do not edit.\n'
            '// Real archived KSFO reports: IEM ASOS archive (public domain) / aviationweather.gov Data API (US Government work);\n'
            '// "Weather: NOAA/NWS Aviation Weather Center; IEM ASOS archive (Iowa Environmental Mesonet)". QA presets (?wx=<id>).\n')
    f.write('export const ENV_PRESETS = ' + json.dumps(out, separators=(',', ':')) + ';\n')
    f.write('// the latest KSFO TAF issued at or before the data/snapshot.js time = the forecast known then (environment_spec.md 3.4;\n'
            '// used by js/env/wx/taf.js beyond the latest METAR, from its valid start); NWS product, public domain\n')
    f.write('export const SNAPSHOT_TAF = ' + json.dumps(snapshot_taf, separators=(',', ':')) + ';\n')
    f.write('// all KSFO TAFs issued on 23 Sep at or before the snapshot time (the app uses the latest issued <= t_env)\n')
    f.write('export const SNAPSHOT_TAFS = ' + json.dumps(snapshot_tafs, separators=(',', ':')) + ';\n')
    f.write('// KSFO METAR/SPECI of the 24 h before the snapshot, observed at or before it (IEM ASOS archive, public domain)\n')
    f.write('export const SNAPSHOT_METARS = ' + json.dumps(snapshot_metars, separators=(',', ':')) + ';\n')
print('wrote', path, os.path.getsize(path), 'bytes,', len(out), 'presets; SNAPSHOT_TAF', snapshot_taf and snapshot_taf['raw'][:60], '; TAFs', len(snapshot_tafs), '; METARs', len(snapshot_metars))
